import XCTest
@testable import WinDock

final class SecureIdentityTests: XCTestCase {
    /// Generated by the host's own src/tls.js (generateTlsIdentity); fingerprint and code as it reports them.
    private let vectorPEM = """
        MIIBbzCCARWgAwIBAgIQMyi//HD6Q0dChIu+NZ9eKjAKBggqhkjOPQQDAjAeMRww
        GgYDVQQDDBNXaW5Eb2NrIHRlc3QtdmVjdG9yMB4XDTI1MTIzMTAwMDAwMFoXDTQ2
        MDEwMTAwMDAwMFowHjEcMBoGA1UEAwwTV2luRG9jayB0ZXN0LXZlY3RvcjBZMBMG
        ByqGSM49AgEGCCqGSM49AwEHA0IABN6Ute/WRqKjoJSVVoDVhuIXSd4eSx516WZT
        8UuHrtr49OZEXiSDjTQoViGidimtWqT6ZW0E1BSg2Z1r2LzvJoKjNTAzMAwGA1Ud
        EwEB/wQCMAAwDgYDVR0PAQH/BAQDAgeAMBMGA1UdJQQMMAoGCCsGAQUFBwMBMAoG
        CCqGSM49BAMCA0gAMEUCIQDV0OMPpVLUzAnD9zXqaNs8yuOlLYdsRUFDZxrUv+Rn
        5gIgZLxIRDVgm4jLpqMSBEd0kzMR7WBYyIRTvOi6sDSguQs=
        """
    private let vectorFingerprint = "d14004840beedfec0e17d92c54d86df5e9daf224bf966c026ac90ba44b9eb775"
    private let hostId = "3f2a9c01-b7e4-4d5e-8a10-0123456789ab"

    private func vectorDER() throws -> Data {
        try XCTUnwrap(Data(base64Encoded: vectorPEM.replacingOccurrences(of: "\n", with: "")))
    }

    func testFingerprintAndCodeMatchHostTestVector() throws {
        let der = try vectorDER()
        XCTAssertEqual(CertificatePin.fingerprint(der: der), vectorFingerprint)
        XCTAssertEqual(CertificatePin.securityCode(vectorFingerprint), "D140-0484-0BEE")
        // The same DER as a SecCertificate, as a TLS handshake would present it.
        let certificate = try XCTUnwrap(SecCertificateCreateWithData(nil, der as CFData))
        var trust: SecTrust?
        XCTAssertEqual(SecTrustCreateWithCertificates(certificate, SecPolicyCreateSSL(true, nil), &trust), errSecSuccess)
        XCTAssertEqual(CertificatePin.leafFingerprint(try XCTUnwrap(trust)), vectorFingerprint)
    }

    func testFingerprintValidation() {
        XCTAssertTrue(CertificatePin.isValid(vectorFingerprint))
        for bad in ["", String(vectorFingerprint.dropLast()), vectorFingerprint.uppercased(), vectorFingerprint + "0",
                    String(repeating: "g", count: 64), "D140-0484-0BEE"] {
            XCTAssertFalse(CertificatePin.isValid(bad), bad)
            XCTAssertNil(CertificatePin.securityCode(bad), bad)
        }
    }

    func testPinDecision() {
        XCTAssertEqual(PinDecision.decide(pinned: nil, presented: vectorFingerprint), .confirm)
        XCTAssertEqual(PinDecision.decide(pinned: vectorFingerprint, presented: vectorFingerprint), .trust)
        XCTAssertEqual(PinDecision.decide(pinned: String(repeating: "0", count: 64), presented: vectorFingerprint), .mismatch)
    }

    func testPinStoreValidatesHostIdAndFingerprint() throws {
        let suite = "WinDockPinStoreTests"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: suite))
        defaults.removePersistentDomain(forName: suite)
        defer { defaults.removePersistentDomain(forName: suite) }
        let store = PinStore(defaults: defaults)
        XCTAssertNil(store.pin(for: hostId))
        XCTAssertTrue(store.setPin(vectorFingerprint, for: hostId))
        XCTAssertEqual(store.pin(for: hostId), vectorFingerprint)
        XCTAssertEqual(store.pin(for: hostId.uppercased()), vectorFingerprint, "Host ids compare case-insensitively")
        for badId in ["", "not-a-uuid", "3f2a9c01b7e44d5e8a100123456789ab", "{3f2a9c01-b7e4-4d5e-8a10-0123456789ab}",
                      "../3f2a9c01-b7e4-4d5e-8a10-0123456789ab"] {
            XCTAssertFalse(PinStore.isValidHostId(badId), badId)
            XCTAssertFalse(store.setPin(vectorFingerprint, for: badId), badId)
            XCTAssertNil(store.pin(for: badId), badId)
        }
        XCTAssertFalse(store.setPin("D140-0484-0BEE", for: hostId))
        XCTAssertEqual(store.pin(for: hostId), vectorFingerprint, "An invalid fingerprint never replaces a pin")
        defaults.set("tampered", forKey: PinStore.keyPrefix + hostId)
        XCTAssertNil(store.pin(for: hostId), "A malformed stored value is not a pin")
        store.setPin(vectorFingerprint, for: hostId)
        store.removePin(for: hostId)
        XCTAssertNil(store.pin(for: hostId))
    }

    func testHealthParsesTlsHint() throws {
        let body = #"{"ok":true,"app":"windock","hostId":"\#(hostId)","hostName":"Studio","tls":{"fingerprint":"\#(vectorFingerprint)","code":"D140-0484-0BEE"}}"#
        let info = try XCTUnwrap(HealthProbe.parse(Data(body.utf8)))
        XCTAssertEqual(info, HealthInfo(hostId: hostId, hostName: "Studio", tlsFingerprint: vectorFingerprint))
        let older = try XCTUnwrap(HealthProbe.parse(Data(#"{"ok":true,"app":"windock","tls":null}"#.utf8)))
        XCTAssertNil(older.tlsFingerprint)
        XCTAssertNil(older.hostId)
    }

    func testDisplayNameIsTruncated() {
        XCTAssertEqual(DockViewController.displayName(String(repeating: "a", count: 100)).count, 60)
        XCTAssertEqual(DockViewController.displayName("  "), "your computer")
    }
}
